const s = await search({ query: "mnemolite search_memory write_memory update_memory", namespace: "mnemolite", limit: 10 });
return s.items.map(i => `${i.path}
  ${i.description}
  ${i.signature}`).join("

");

const queries = [
  ["cas jouet terrain repo notes", ["project:*"]],
  ["terrain README app.py cas jouet deux fichiers", null]
];
const out = [];
for (const [q, tags] of queries) {
  try {
    const r = await tools.mnemolite.search_memory({ query: q, search_mode: "hybrid", limit: 10, tags });
    out.push(`=== ${q} ===\n${JSON.stringify(r).slice(0, 3000)}`);
  } catch (e) {
    out.push(`=== ${q} === ERROR ${e.message}`);
  }
}
return out.join("\n\n");

const content = `FAIT CONFIRME (2026-10-22, dépôt /home/giak/projects/aidd-device-work/2026-10-18-085308-cas-jouet/terrain, inspection directe du dépôt).

INVENTAIRE (source primaire : lecture des fichiers + \`git ls-files\` = 2 lignes) :
- \`README.md\` (56 o, 3 lignes) : titre « terrain du cas jouet » + « Deux fichiers, et rien de plus. » ; aucune section installation/usage/test.
- \`app.py\` (19 o, 1 ligne) : \`print("cas jouet")\` ; aucun import, aucune fonction, aucun garde \`__main__\`, aucune CLI. \`python3 app.py\` écrit « cas jouet » sur stdout, code de sortie 0 (Python 3.12.3).

ÉTAT GIT : arbre propre avant l'ajout de notes ; HEAD détaché sur \`62c48e1\` (« cas jouet : deux fichiers », 2026-10-18 07:00:00 +0200) ; branche \`main\` existante ; remote \`origin\` vers un chemin local \`.../cas-jouet/origine/terrain\` (jamais lu) ; aucun tag ; ni .gitignore, ni dépendances, ni tests, ni CI.

NOTES ÉCRITES : \`aidd_docs/NOTES.md\` (11 lignes, une règle par ligne, format Markdown à puces) — playbook mini-framework-origin/PLAYBOOK.md (tableau de lecture → confirmation opérateur → un seul fichier écrit à l'emplacement demandé). Le dépôt n'avait aucune note avant cette écriture (recherche Mnemolite préalable : 0 résultat pour ce projet).`;

try {
  const r = await tools.mnemolite.write_memory({
    title: "cas-jouet/terrain : inventaire réel (2 fichiers) et création de aidd_docs/NOTES.md (2026-10-22)",
    content,
    memory_type: "note",
    tags: ["project:cas-jouet-terrain", "notes", "inventaire", "git", "status:CONFIRME", "verifie-2026-10-22"],
    author: "opencode"
  });
  return JSON.stringify(r).slice(0, 2000);
} catch (e) {
  return "ERROR: " + e.message;
}
